import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Espace de travail","description":"","frontmatter":{},"headers":[],"relativePath":"fr/concepts/workspace.md","filePath":"fr/concepts/workspace.md","lastUpdated":1784904021000}'),n={name:"fr/concepts/workspace.md"};function o(p,e,c,l,d,r){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="espace-de-travail" tabindex="-1">Espace de travail <a class="header-anchor" href="#espace-de-travail" aria-label="Permalink to &quot;Espace de travail&quot;">​</a></h1><p>L&#39;espace de travail est le répertoire où swag2mcp stocke toutes ses données — configuration, specs en cache, fichiers de spécification locaux, réponses sauvegardées et scripts d&#39;authentification.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/                          # Racine de l&#39;espace de travail (par défaut)</span></span>
<span class="line"><span>├── swag2mcp.yaml                     # Fichier de configuration</span></span>
<span class="line"><span>├── cache/                            # Fichiers de spécification distants en cache</span></span>
<span class="line"><span>│   ├── a1b2c3d4e5f6...spec          # Contenu de la spec en cache</span></span>
<span class="line"><span>│   └── a1b2c3d4e5f6...meta          # Métadonnées du cache (JSON)</span></span>
<span class="line"><span>├── specs/                            # Fichiers de spécification locaux</span></span>
<span class="line"><span>│   └── mon-api.yaml</span></span>
<span class="line"><span>├── responses/                        # Réponses API sauvegardées (grandes réponses)</span></span>
<span class="line"><span>│   ├── meteo-get-forecast-abc123.json</span></span>
<span class="line"><span>│   └── response-fragment-def456.json</span></span>
<span class="line"><span>└── auth_scripts/                     # Scripts d&#39;authentification</span></span>
<span class="line"><span>    ├── meteo.sh                      # Script shell Unix</span></span>
<span class="line"><span>    └── meteo.bat                     # Script batch Windows</span></span></code></pre></div><h2 id="chemin-par-defaut" tabindex="-1">Chemin par défaut <a class="header-anchor" href="#chemin-par-defaut" aria-label="Permalink to &quot;Chemin par défaut&quot;">​</a></h2><ul><li><strong>Linux/macOS</strong> : <code>~/.swag2mcp/</code></li><li><strong>Windows</strong> : <code>%USERPROFILE%\\.swag2mcp\\</code></li></ul><h2 id="chemin-personnalise" tabindex="-1">Chemin personnalisé <a class="header-anchor" href="#chemin-personnalise" aria-label="Permalink to &quot;Chemin personnalisé&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/espace-travail</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./mon-espace-travail</span></span></code></pre></div><h2 id="repertoires" tabindex="-1">Répertoires <a class="header-anchor" href="#repertoires" aria-label="Permalink to &quot;Répertoires&quot;">​</a></h2><h3 id="cache" tabindex="-1">cache/ <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;cache/&quot;">​</a></h3><p>Stocke les fichiers de spécification distants téléchargés. Chaque fichier est mis en cache avec un hachage SHA-256 de son URL comme nom de fichier :</p><ul><li><code>{hachage}.spec</code> — le contenu du fichier de spécification en cache</li><li><code>{hachage}.meta</code> — métadonnées JSON (URL source, heure de mise en cache, TTL)</li></ul><p>Chaque fichier en cache a un TTL aléatoire entre 1 heure et 48 heures. Le cache est automatiquement vérifié à chaque démarrage — si une entrée valide (non expirée) existe, elle est réutilisée sans téléchargement.</p><p><strong>Commandes :</strong></p><ul><li><code>swag2mcp update</code> — vide le cache et retélécharge toutes les specs</li><li><code>swag2mcp clean</code> — vide le cache et les réponses</li></ul><h3 id="specs" tabindex="-1">specs/ <a class="header-anchor" href="#specs" aria-label="Permalink to &quot;specs/&quot;">​</a></h3><p>Stocke les fichiers de spécification locaux vers lesquels les collections pointent via <code>location: specs/{nom}</code>. Les fichiers ici sont utilisés directement sans mise en cache.</p><p>Ce répertoire est rempli par :</p><ul><li><code>swag2mcp import &amp;lt;source&amp;gt; &amp;lt;nom&amp;gt;</code> — télécharge une spec distante et la sauvegarde ici</li><li><code>swag2mcp export</code> — copie les specs ici dans le ZIP d&#39;exportation</li><li>Placement manuel — vous pouvez copier vous-même des fichiers de spécification ici</li></ul><h3 id="responses" tabindex="-1">responses/ <a class="header-anchor" href="#responses" aria-label="Permalink to &quot;responses/&quot;">​</a></h3><p>Stocke les réponses API qui dépassent la limite <code>max_response_size</code> (par défaut 1 Mo). Lorsque le LLM invoque un point d&#39;accès et que la réponse est trop volumineuse, swag2mcp la sauvegarde ici et retourne une référence de fichier à la place.</p><p>Convention de nommage : <code>{domaine}-{méthode}-{chemin_avec_tirets_bas}-{6car_hex}.json</code></p><p>Les anciennes réponses sont nettoyées automatiquement après 48 heures au démarrage du serveur MCP.</p><h3 id="auth-scripts" tabindex="-1">auth_scripts/ <a class="header-anchor" href="#auth-scripts" aria-label="Permalink to &quot;auth_scripts/&quot;">​</a></h3><p>Stocke les scripts d&#39;authentification pour le type d&#39;auth <code>script</code>. Chaque script est nommé d&#39;après le domaine de la spec.</p><h4 id="convention-de-nommage" tabindex="-1">Convention de nommage <a class="header-anchor" href="#convention-de-nommage" aria-label="Permalink to &quot;Convention de nommage&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Plateforme</th><th>Nom de fichier</th><th>Exemple</th></tr></thead><tbody><tr><td>Unix (Linux, macOS)</td><td><code>{domaine}.sh</code></td><td><code>meteo.sh</code></td></tr><tr><td>Windows</td><td><code>{domaine}.bat</code></td><td><code>meteo.bat</code></td></tr></tbody></table><p>Le domaine ne doit pas contenir de caractères <code>/</code> ou <code>\\</code>.</p><h4 id="comment-les-scripts-fonctionnent" tabindex="-1">Comment les scripts fonctionnent <a class="header-anchor" href="#comment-les-scripts-fonctionnent" aria-label="Permalink to &quot;Comment les scripts fonctionnent&quot;">​</a></h4><ol><li>swag2mcp exécute le script avec un délai d&#39;attente de 30 secondes</li><li>Le script doit produire du JSON valide sur stdout</li><li>swag2mcp analyse le JSON et utilise le jeton pour les requêtes API</li></ol><h4 id="format-de-sortie-attendu" tabindex="-1">Format de sortie attendu <a class="header-anchor" href="#format-de-sortie-attendu" aria-label="Permalink to &quot;Format de sortie attendu&quot;">​</a></h4><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;votre-jeton-ici&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Champ</th><th>Type</th><th>Requis</th><th>Description</th></tr></thead><tbody><tr><td><code>token</code></td><td>string</td><td>✅</td><td>Le jeton d&#39;authentification</td></tr><tr><td><code>access_token</code></td><td>string</td><td>❌</td><td>Alternative à <code>token</code> (vérifié en premier)</td></tr><tr><td><code>token_type</code></td><td>string</td><td>❌</td><td>Type de jeton (par ex., « Bearer »)</td></tr><tr><td><code>expires_in</code></td><td>number</td><td>❌</td><td>Durée de vie du jeton en secondes (défaut : 3600)</td></tr></tbody></table><h4 id="execution" tabindex="-1">Exécution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Exécution&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Plateforme</th><th>Commande</th></tr></thead><tbody><tr><td>Unix</td><td><code>sh {domaine}.sh</code></td></tr><tr><td>Windows</td><td><code>cmd /c {domaine}.bat</code></td></tr></tbody></table><h4 id="mise-en-cache-du-jeton" tabindex="-1">Mise en cache du jeton <a class="header-anchor" href="#mise-en-cache-du-jeton" aria-label="Permalink to &quot;Mise en cache du jeton&quot;">​</a></h4><p>Le jeton est mis en cache en mémoire jusqu&#39;à son expiration. À chaque appel API, swag2mcp vérifie d&#39;abord le cache — le script n&#39;est exécuté que lorsque le jeton en cache a expiré.</p><h4 id="creation-de-stub" tabindex="-1">Création de stub <a class="header-anchor" href="#creation-de-stub" aria-label="Permalink to &quot;Création de stub&quot;">​</a></h4><p>Lorsque vous configurez <code>auth: { type: script, config: { domain: &quot;monapi&quot; } }</code>, swag2mcp crée un script stub automatiquement :</p><p><strong>Unix (<code>auth_scripts/monapi.sh</code>) :</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;token&quot;: &quot;votre-jeton-ici&quot;, &quot;expires_in&quot;: 3600}&#39;</span></span></code></pre></div><p><strong>Windows (<code>auth_scripts/monapi.bat</code>) :</strong></p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;votre-jeton-ici&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 3600}</span></span></code></pre></div><p>Remplacez le jeton factice par votre logique d&#39;authentification réelle.</p><h4 id="nettoyage-des-orphelins" tabindex="-1">Nettoyage des orphelins <a class="header-anchor" href="#nettoyage-des-orphelins" aria-label="Permalink to &quot;Nettoyage des orphelins&quot;">​</a></h4><p>Lorsque vous supprimez une spec, son script d&#39;authentification devient orphelin. swag2mcp supprime automatiquement les scripts orphelins lors de :</p><ul><li><code>swag2mcp update</code></li><li><code>swag2mcp clean</code></li></ul><h2 id="commandes" tabindex="-1">Commandes <a class="header-anchor" href="#commandes" aria-label="Permalink to &quot;Commandes&quot;">​</a></h2><h3 id="update" tabindex="-1">update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;update&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [chemin]</span></span></code></pre></div><p>Valide la configuration, vide le cache et les réponses, puis retélécharge tous les fichiers de spécification. Assure également que les scripts d&#39;authentification existent et supprime les scripts orphelins.</p><p>Utilisez cette commande après :</p><ul><li>Ajout ou suppression de collections</li><li>Changement d&#39;emplacements de collections</li><li>Modification de fichiers de spécification qui nécessitent un re-cache</li></ul><h3 id="clean" tabindex="-1">clean <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;clean&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [chemin]</span></span></code></pre></div><p>Supprime tout le contenu de <code>cache/</code> et <code>responses/</code>, plus les scripts d&#39;authentification orphelins. Ne remet PAS en cache les specs — utilisez <code>update</code> pour cela.</p><h3 id="validate" tabindex="-1">validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;validate&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [chemin]</span></span></code></pre></div><p>Valide la configuration, y compris tous les emplacements de collection. Voir <a href="./../cli/validate">CLI : validate</a>.</p><h2 id="exportation-et-importation" tabindex="-1">Exportation et importation <a class="header-anchor" href="#exportation-et-importation" aria-label="Permalink to &quot;Exportation et importation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exporter l&#39;espace de travail vers ZIP (nom par défaut : swag2mcp-backup-{date}.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exporter vers un chemin spécifique</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/espace-travail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/sauvegarde.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exporter uniquement des specs spécifiques</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restaurer depuis une sauvegarde</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/sauvegarde.zip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/espace-travail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/sauvegarde.zip</span></span></code></pre></div><p>L&#39;exportation inclut : <code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>. Le cache et les réponses sont exclus (ce sont des données locales).</p><h2 id="gitignore" tabindex="-1">.gitignore <a class="header-anchor" href="#gitignore" aria-label="Permalink to &quot;.gitignore&quot;">​</a></h2><p>Si votre espace de travail se trouve dans un dépôt Git, ajoutez ces entrées à <code>.gitignore</code> :</p><div class="language-gitignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># swag2mcp — données locales uniquement</span></span>
<span class="line"><span>.swag2mcp/cache/</span></span>
<span class="line"><span>.swag2mcp/responses/</span></span></code></pre></div><p>Les répertoires <code>cache/</code> et <code>responses/</code> contiennent des données locales spécifiques à la machine qui ne doivent pas être commitées. Tout le reste (<code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>) doit être dans le dépôt afin que la configuration soit partagée dans toute l&#39;équipe.</p>`,66)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
